39. import {
40.   SLUG_MAX_LENGTH,
41.   questionnaireBasicSchema,
42. } from "./questionnaireFormSchema";
43. 
44. const COPY_SUFFIX = "-copy";
45. 
46. /**
47.  * `{slug}-copy`, clamped so it still respects the shared slug length rule
48.  * even when the source slug is already near the SLUG_MAX_LENGTH ceiling —
49.  * truncates the base rather than the suffix so the result still reads as a
50.  * copy.
51.  */
52. function defaultCloneSlug(slug: string): string {
53.   const base = slug
54.     .slice(0, SLUG_MAX_LENGTH - COPY_SUFFIX.length)
55.     .replace(/-+$/, "");
56.   return `${base}${COPY_SUFFIX}`;
57. }
58. 
59. interface CloneFormValues {
60.   title: string;
61.   slug: string;
62. }
63. 
64. interface CloneQuestionnaireDialogProps {
65.   scope: QuestionnaireScope;
66.   questionnaire: QuestionnaireRead;
67.   open: boolean;
68.   onOpenChange: (open: boolean) => void;
69. }
70. 
71. export function CloneQuestionnaireDialog({
72.   scope,
73.   questionnaire,
74.   open,
75.   onOpenChange,
76. }: CloneQuestionnaireDialogProps) {
77.   const { t } = useTranslation();
78.   const queryClient = useQueryClient();
79. 
80.   const cloneSchema = useMemo(
81.     () => questionnaireBasicSchema(t).pick({ title: true, slug: true }),
82.     [t],
83.   );
84. 
85.   const form = useForm<CloneFormValues>({
86.     resolver: zodResolver(cloneSchema),
87.     defaultValues: {
88.       title: t("cloned_questionnaire_title", { title: questionnaire.title }),
89.       slug: defaultCloneSlug(questionnaire.slug),
90.     },
91.   });
92. 
93.   // Re-seed the defaults every time the dialog opens — the form stays
94.   // mounted between opens, and the underlying questionnaire's title/slug
95.   // may have changed (e.g. the detail form was edited) since the last time.
96.   useEffect(() => {
97.     if (open) {
98.       form.reset({
99.         title: defaultCloneTitle(questionnaire.title),
100.         slug: defaultCloneSlug(questionnaire.slug),
101.       });
102.     }
103.     // eslint-disable-next-line react-hooks/exhaustive-deps
104.   }, [open, questionnaire.title, questionnaire.slug]);
105. 
106.   const { mutate: clone, isPending } = useMutation({
107.     mutationFn: mutate(questionnaireApi.createV2),
108.     onSuccess: (created: QuestionnaireRead) => {
109.       queryClient.invalidateQueries({ queryKey: questionnaireKeys.all });
110.       toast.success(t("questionnaire_cloned_successfully"));
111.       onOpenChange(false);
112.       navigate(`${scope.basePath}/${created.id}`);
113.     },
114.   });
115. 
116.   const onSubmit = (values: CloneFormValues) => {
117.     clone({
118.       title: values.title,
119.       slug: values.slug,
120.       description: questionnaire.description,
121.       version: questionnaire.version ? String(questionnaire.version) : "1.0",
122.       code: questionnaire.code,
123.       status: "draft",
124.       subject_type: questionnaire.subject_type,
125.       questions: regenerateQuestionIds(
126.         structuredClone(questionnaire.questions),
127.       ),
128.       ...scopeCreateFields(scope),
129.     });
130.   };
131. 
132.   return (
133.     <Dialog open={open} onOpenChange={onOpenChange}>
134.       <DialogContent>
135.         <DialogHeader>
136.           <DialogTitle>{t("clone_questionnaire")}</DialogTitle>
137.           <DialogDescription>
138.             {t("clone_questionnaire_draft_description")}
139.           </DialogDescription>
140.         </DialogHeader>
141.         <Form {...form}>
142.           <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
143.             <FormField
144.               control={form.control}
145.               name="title"
146.               render={({ field }) => (
147.                 <FormItem>
148.                   <FormLabel aria-required>{t("title")}</FormLabel>
149.                   <FormControl>
150.                     <Input {...field} />
151.                   </FormControl>
152.                   <FormMessage />
153.                 </FormItem>
154.               )}
155.             />
156.             <FormField
157.               control={form.control}
158.               name="slug"
159.               render={({ field }) => (
160.                 <FormItem>
161.                   <FormLabel aria-required>{t("slug")}</FormLabel>
162.                   <FormControl>
163.                     <Input {...field} />
164.                   </FormControl>
165.                   <FormMessage />
166.                 </FormItem>
167.               )}
168.             />
169.             <DialogFooter>
170.               <Button
171.                 type="button"
172.                 variant="outline"
173.                 onClick={() => onOpenChange(false)}
174.               >
175.                 {t("cancel")}
176.               </Button>
177.               <Button type="submit" disabled={isPending}>
178.                 {t("clone_form")}
179.               </Button>
180.             </DialogFooter>
181.           </form>
182.         </Form>
183.       </DialogContent>
184.     </Dialog>
185.   );
186. }
