400.   // parent effects on mount, and this hook always sits below the fill
401.   // session's dirty-tracking subscription (`fill/draft/useFillAutosave.ts`,
402.   // mounted by `QuestionnaireFillPage.tsx`) — a synchronous commit here
403.   // lands before that subscription exists, so the seed never marks the form
404.   // dirty (no Draft chip, no unsaved-changes warning, a silently lost
405.   // edit). `queueMicrotask` runs strictly after the whole synchronous
406.   // effect-flush pass (every ancestor effect included) and drains before
407.   // the next paint, so the seeded row still shows from the first frame.
408.   // `seeded.current` still flips SYNCHRONOUSLY in the effect body, so the
409.   // one-shot latch and its StrictMode safety are unaffected — only the
410.   // write moves, not the decision.
411.   //
412.   // COUPLING: this also relies on a live subscription existing when the
413.   // microtask drains. `useFillAutosave`'s subscription effect resolves
414.   // each form's store through a ref-backed lookup (`getStore` reads
415.   // `QuestionnaireFillPage.tsx`'s `storesRef`), so its first run already
416.   // subscribes to the durable store. If dirty-tracking ever subscribed by
417.   // keying off state instead, a deferred write could drain between two
418.   // subscription instances and this bug would silently return.
419.   //
420.   // LIVENESS GUARD — `alive`, not a cleanup-driven `cancelled` flag. A
421.   // cleanup returned from THIS effect breaks under StrictMode's
422.   // mount→cleanup→mount (run synchronously, before any microtask drains):
423.   // pass 1 schedules the commit, the simulated unmount cancels it, pass 2
424.   // sees `seeded.current` already true and schedules nothing — the seed
425.   // never commits in dev. Instead `alive` is armed by a separate dep-less
426.   // effect: a StrictMode remount re-arms it in the same synchronous
427.   // sequence (microtask reads true, seed proceeds); a real unmount leaves
428.   // it false (seed skipped). `updateResponse`'s own `if (!current) return`
429.   // does NOT cover this window — an unmounted question can still have a
430.   // live `responsesAtom` entry while another question's editor is mounted.
431.   const alive = useRef(true);
432.   useEffect(() => {
433.     alive.current = true;
434.     return () => {
435.       alive.current = false;
436.     };
437.   });
438. 
439.   const seeded = useRef(false);
440.   useEffect(() => {
441.     if (seeded.current) return;
442.     const decision = decideInitialEditsSeed(edits, initialEdits);
443.     if (decision === "wait") return;
444.     seeded.current = true;
445.     if (decision === "skip" || !initialEdits) return;
446.     let next: EditLog<TRow> = edits;
447.     for (const edit of initialEdits) {
448.       next = applyEditToLog(next, edit, applyOpts);
449.     }
450.     queueMicrotask(() => {
451.       if (alive.current) commit(next);
452.     });
453.   }, [initialEdits, edits, applyOpts, commit]);
454. 
455.   const applyEdit = useCallback(
456.     (edit: RowEdit<TRow>) => {
457.       if (disabled) return;
458.       commit(applyEditToLog(edits, edit, applyOpts));
459.     },
460.     [disabled, edits, applyOpts, commit],
461.   );
462. 
463.   const resetEdits = useCallback(() => {
464.     if (disabled) return;
465.     commit([]);
466.     // A Discard clears `droppedEdits` too, deliberately: "forget everything
467.     // I did this session" includes the restore-notice record — a notice
468.     // naming rows lost from a PRIOR restore would be stale the instant the
469.     // clinician explicitly abandoned every pending edit.
470.     setDroppedEdits([]);
471.   }, [disabled, commit]);
472. 
473.   const isDuplicate = useCallback(
474.     (row: TRow) => findDuplicateCandidates(rows, duplicateKey, [row])[0],
475.     [rows, duplicateKey],
476.   );
477. 
478.   const addRows = useCallback(
479.     (candidates: readonly TRow[]): AddRowResult[] => {
480.       if (disabled) {
481.         return candidates.map(() => ({ ok: false, reason: "disabled" }));
482.       }
483.       const duplicates = findDuplicateCandidates(
484.         rows,
485.         duplicateKey,
486.         candidates,
487.       );
488.       const results: AddRowResult[] = [];
489.       let next = edits;
490.       for (let i = 0; i < candidates.length; i++) {
491.         if (duplicates[i]) {
492.           results.push({ ok: false, reason: "duplicate" });
493.           continue;
494.         }
495.         const rowId = newRowId();
496.         next = applyEditToLog(
497.           next,
498.           { rowId, op: "add", patch: candidates[i] },
499.           applyOpts,
500.         );
501.         results.push({ ok: true, rowId });
502.       }
503.       // Every candidate was a duplicate (or the batch was empty): `next`
504.       // is still the SAME reference as `edits` (no `applyEditToLog` call
505.       // ran), so skip the commit entirely — a fully-rejected batch must
506.       // not write to the atom or clear this question's errors.
507.       if (next !== edits) commit(next);
508.       return results;
509.     },
510.     [disabled, rows, duplicateKey, edits, applyOpts, commit],
511.   );
512. 
513.   const addRow = useCallback(
514.     (row: TRow): AddRowResult => addRows([row])[0],
515.     [addRows],
516.   );
517. 
518.   const updateRow = useCallback(
519.     (rowId: RowId, patch: Partial<TRow>) => {
520.       if (disabled) return;
521.       const current = rows.find((entry) => entry.rowId === rowId)?.row;
522.       if (!current) return;
523.       commit(
524.         applyEditToLog(
525.           edits,
526.           {
527.             rowId,
528.             op: "update",
529.             patch: mergePatch(current, patch, normalizePatch),
530.           },
531.           applyOpts,
532.         ),
533.       );
534.     },
535.     [disabled, rows, normalizePatch, edits, applyOpts, commit],
536.   );
537. 
538.   const removeRow = useCallback(
539.     (rowId: RowId) => {
540.       if (disabled) return;
541.       const entry = rows.find((row) => row.rowId === rowId);
542.       if (!entry) return;
543.       commit(
544.         applyEditToLog(
545.           edits,
546.           resolveRemoveIntent(entry, softDelete),
547.           applyOpts,
548.         ),
549.       );
550.     },
551.     [disabled, rows, softDelete, edits, applyOpts, commit],
552.   );
553. 
554.   const setRow = useCallback(
555.     (patch: Partial<TRow>) => {
556.       if (disabled) return;
557.       const entry = rows[0];
558.       const edit = resolveSetRow({
559.         currentRow: entry?.row,
560.         currentRowId: entry?.rowId,
561.         patch,
562.         createSeed,
563.         singletonRowId,
564.         normalizePatch,
565.         questionId,
566.       });
567.       commit(applyEditToLog(edits, edit, applyOpts));
568.     },
569.     [
570.       disabled,
571.       rows,
572.       createSeed,
573.       singletonRowId,
574.       normalizePatch,
575.       questionId,
576.       edits,
577.       applyOpts,
578.       commit,
579.     ],
580.   );
581. 
582.   const clearRow = useCallback(() => {
583.     if (disabled) return;
584.     const entry = rows[0];
585.     if (!entry) return;
586.     commit(
587.       applyEditToLog(edits, resolveRemoveIntent(entry, softDelete), applyOpts),
588.     );
589.   }, [disabled, rows, softDelete, edits, applyOpts, commit]);
590. 
591.   const base: StructuredRowsBase<TRow> = {
592.     edits,
593.     isDirty: edits.length > 0,
594.     orphanRowIds,
595.     droppedEdits,
596.     applyEdit,
597.     resetEdits,
598.   };
599. 
600.   // The runtime branch matches the `Mode` type parameter by construction
601.   // (callers pick `mode` and get the correspondingly-narrowed return type),
602.   // but nothing in the type system connects a runtime string comparison to
603.   // a conditional type — the cast is the one unavoidable seam between them,
604.   // not a domain decision.
605.   if (mode === "single") {
606.     return {
607.       ...base,
608.       row: rows[0],
609.       setRow,
610.       clearRow,
611.     } as unknown as StructuredRowsController<TRow, Mode>;
612.   }
613.   return {
614.     ...base,
615.     rows,
616.     addRow,
617.     addRows,
618.     updateRow,
619.     removeRow,
620.     isDuplicate,
621.   } as unknown as StructuredRowsController<TRow, Mode>;
622. }

