        s=lines[i]
        st=s.strip()
        if st.startswith('//'):
            start=i+1; block=[]
            while i<len(lines) and lines[i].strip().startswith('//'):
                block.append(lines[i]); i+=1
            c='\n'.join(block)
            if terms.search(c) or len(block)>10:
                out.append((start,i,c))
            continue
        if '/*' in s:
            start=i+1; block=[s]
            while '*/' not in lines[i] and i+1<len(lines):
                i+=1; block.append(lines[i])
            i+=1
            c='\n'.join(block)
            if terms.search(c) or len(block)>12:
                out.append((start,i,c))
            continue
        i+=1
    if out:
        print('\n###',p)
        for start,end,c in out:
            print(f'-- lines {start}-{end} ({end-start+1})')
            print(c[:1200])
