1. import { useQueryClient } from "@tanstack/react-query";
2. import { useCallback, useEffect, useRef, useState } from "react";
3. import { useTranslation } from "react-i18next";
4. import { toast } from "sonner";
5. 
6. import { responsesAtom } from "@/components/QuestionnaireV2/form/engine/store";
7. import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";
8. 
9. import query from "@/Utils/request/query";
10. import type { QuestionnaireResponse } from "@/types/questionnaire/form";
11. import type { QuestionnaireRead } from "@/types/questionnaire/questionnaire";
12. import questionnaireApi from "@/types/questionnaire/questionnaireApi";
13. 
14. import type { FormStore } from "./StoreRegistrar";
15. import type { DraftFormSnapshot } from "./draft/fillDraftStore";
16. import {
17.   mergeDraftIntoSeed,
18.   preserveExcludedStructured,
19. } from "./draft/fillDraftStore";
20. import type { FillFormEntry } from "./formSession";
21. 
22. interface UseFillSessionFormsArgs {
23.   /** The route-mounted questionnaire — seeds the session's one PRIMARY
24.    *  form. Only read once (the initial `useState` seed); later identity
25.    *  changes have no effect. */
26.   questionnaire: QuestionnaireRead;
27.   /** Resumed server draft responses, seeded into the primary form at
28.    *  creation only. */
29.   serverDraftResponses?: Record<string, QuestionnaireResponse>;
30.   getStore: (key: string) => FormStore | undefined;
31. }
32. 
33. /**
34.  * The fill session's form list plus everything that mutates it: adding a
35.  * questionnaire (by hand or via a drafted resume), removing one, and the
36.  * retained-snapshot bookkeeping for forms the draft is still carrying
37.  * without a live store (a resume whose re-fetch failed).
38.  */
39. export function useFillSessionForms({
40.   questionnaire,
41.   serverDraftResponses,
42.   getStore,
43. }: UseFillSessionFormsArgs) {
44.   const { t } = useTranslation();
45.   const queryClient = useQueryClient();
46. 
47.   // The session: the route-mounted questionnaire plus anything added to
48.   // the same submission. Each entry owns one provider and one store.
49.   const [forms, setForms] = useState<FillFormEntry[]>(() => [
50.     {
51.       key: questionnaire.id,
52.       questionnaire,
53.       isPrimary: true,
54.       initialResponses: serverDraftResponses,
55.     },
56.   ]);
57. 
58.   const addQuestionnaire = useCallback(
59.     (
60.       added: QuestionnaireRead,
61.       initialResponses?: Record<string, QuestionnaireResponse>,
62.     ) => {
63.       setForms((previous) =>
64.         previous.some((form) => form.key === added.id)
65.           ? previous
66.           : [
67.               ...previous,
68.               {
69.                 key: added.id,
70.                 questionnaire: added,
71.                 isPrimary: false,
72.                 initialResponses,
73.               },
74.             ],
75.       );
76.     },
77.     [],
78.   );
79.   const removeForm = useCallback((key: string) => {
80.     setForms((previous) =>
81.       previous.filter((form) => form.key !== key || form.isPrimary),
82.     );
83.   }, []);
84. 
85.   // Snapshots that belong to the draft but are not (yet) live forms. They
86.   // stay in the persisted draft (see `saveFillDraft`'s `retained`) — the
87.   // ways a resume can fail are NOT the same: a version bump means the
88.   // answers can no longer be trusted onto the new tree and dropping them
89.   // is correct, while a network error means try again later, and
90.   // destroying the clinician's only copy over it is not.
91.   const [retainedSnapshots, setRetainedSnapshots] = useState<
92.     DraftFormSnapshot[]
93.   >([]);
94.   const dropRetainedSnapshot = useCallback((questionnaireId: string) => {
95.     setRetainedSnapshots((previous) =>
96.       previous.filter((entry) => entry.questionnaireId !== questionnaireId),
97.     );
98.   }, []);
99. 
100.   // Read by resume callbacks that must see the CURRENT session without
101.   // re-creating themselves per forms change. Effect-synced, which is
102.   // enough: every reader is an event-handler-initiated async path that
103.   // runs strictly after the commit that changed `forms`.
104.   const formsRef = useRef(forms);
105.   useEffect(() => {
106.     formsRef.current = forms;
107.   }, [forms]);
108. 
109.   /** Resume for the non-primary snapshots. Every snapshot is RETAINED
110.    *  first — during the re-fetch window it is neither a live form nor
111.    *  retained otherwise, and a persist fired in that window (a keystroke
112.    *  in the primary) would silently drop it from the stored draft; a
113.    *  close/crash then makes the loss permanent. From that safe baseline
114.    *  each snapshot either becomes a live form (fetched, version intact,
115.    *  seeded — or merged into the SAME questionnaire if the clinician
116.    *  already added it by hand), is deliberately dropped (version moved
117.    *  on: the answers can no longer be trusted onto the new tree), or
118.    *  stays retained (fetch failed — try again later). */
119.   const onResumeAddedForms = useCallback(
120.     (snapshots: DraftFormSnapshot[]) => {
121.       setRetainedSnapshots((previous) => {
122.         const seen = new Set(previous.map((entry) => entry.questionnaireId));
123.         return [
124.           ...previous,
125.           ...snapshots.filter(
126.             (snapshot) => !seen.has(snapshot.questionnaireId),
127.           ),
128.         ];
129.       });
130.       void (async () => {
131.         for (const snapshot of snapshots) {
132.           // Already in the session (the clinician added it by hand before
133.           // pressing Resume): apply the snapshot to the live store the
134.           // same way the primary form's resume overlay does — dropping it
135.           // silently would erase the drafted answers from the stored
136.           // draft on the very next persist.
137.           const existing = formsRef.current.find(
138.             (form) => form.key === snapshot.questionnaireId,
139.           );
140.           if (existing) {
141.             if (
142.               String(existing.questionnaire.version) !==
143.               snapshot.questionnaireVersion
144.             ) {
145.               dropRetainedSnapshot(snapshot.questionnaireId);
146.               toast.warning(
147.                 t("fill_draft_form_dropped", {
148.                   title: existing.questionnaire.title,
149.                 }),
150.               );
151.               continue;
152.             }
153.             const store = getStore(existing.key);
154.             if (store) {
155.               store.set(
156.                 responsesAtom,
157.                 preserveExcludedStructured(
158.                   store.get(responsesAtom),
159.                   mergeDraftIntoSeed(
160.                     existing.questionnaire.questions,
161.                     snapshot.responses,
162.                   ),
163.                 ),
164.               );
165.             }
166.             dropRetainedSnapshot(snapshot.questionnaireId);
167.             continue;
168.           }
169.           try {
170.             const fetched = await queryClient.fetchQuery({
171.               queryKey: questionnaireKeys.detail(snapshot.questionnaireId),
172.               queryFn: query(questionnaireApi.get, {
173.                 pathParams: { id: snapshot.questionnaireId },
174.               }),
175.             });
176.             if (String(fetched.version) !== snapshot.questionnaireVersion) {
177.               dropRetainedSnapshot(snapshot.questionnaireId);
178.               toast.warning(
179.                 t("fill_draft_form_dropped", { title: fetched.title }),
180.               );
181.               continue;
182.             }
183.             addQuestionnaire(
184.               fetched,
185.               mergeDraftIntoSeed(fetched.questions, snapshot.responses),
186.             );
187.             dropRetainedSnapshot(snapshot.questionnaireId);
188.           } catch {
189.             // Transient by assumption: the app's query default is
190.             // retry:false, so one network blip lands here. The snapshot
191.             // keeps its place in the stored draft instead of being erased
192.             // by the next persist. The snapshot's stored title is the only
193.             // human name left when the questionnaire cannot be fetched;
194.             // drafts written before that field existed fall back to the id.
195.             toast.warning(
196.               t("fill_draft_form_unavailable", {
197.                 title: snapshot.title ?? snapshot.questionnaireId,
198.               }),
199.             );
200.           }
201.         }
202.       })();
203.     },
204.     [queryClient, addQuestionnaire, getStore, dropRetainedSnapshot, t],
205.   );
206. 
207.   /** The in-session picker's add. When the picked questionnaire matches a
208.    *  RETAINED snapshot (its resume re-fetch failed earlier), that snapshot
209.    *  IS the drafted form — seed from it instead of mounting empty, which
210.    *  would displace the snapshot from the stored draft on the next
211.    *  persist. A version drift drops it with the same toast as resume. */
212.   const addQuestionnaireFromPicker = useCallback(
213.     (selected: QuestionnaireRead) => {
214.       const snapshot = retainedSnapshots.find(
215.         (entry) => entry.questionnaireId === selected.id,
216.       );
217.       if (!snapshot) {
218.         addQuestionnaire(selected);
219.         return;
220.       }
221.       dropRetainedSnapshot(selected.id);
222.       if (String(selected.version) !== snapshot.questionnaireVersion) {
223.         toast.warning(t("fill_draft_form_dropped", { title: selected.title }));
224.         addQuestionnaire(selected);
225.         return;
226.       }
227.       addQuestionnaire(
228.         selected,
229.         mergeDraftIntoSeed(selected.questions, snapshot.responses),
230.       );
231.     },
232.     [retainedSnapshots, addQuestionnaire, dropRetainedSnapshot, t],
233.   );
234. 
235.   return {
236.     forms,
237.     addQuestionnaire,
238.     removeForm,
239.     retainedSnapshots,
240.     onResumeAddedForms,
241.     addQuestionnaireFromPicker,
242.   };
243. }
244.

