91.  *  however enabled the child's own conditions are. */
92. function findQuestionPath(
93.   questions: Question[],
94.   linkId: string,
95. ): Question[] | undefined {
96.   for (const question of questions) {
97.     if (question.link_id === linkId) return [question];
98.     const nested = findQuestionPath(question.questions ?? [], linkId);
99.     if (nested) return [question, ...nested];
