125.  *  every handle method is meant to be JSON-safe, since it may be read
126.  *  across module federation or Playwright's `page.evaluate`. */
127. function toPlainEntry(entry: ResponseValue): PlainValueEntry {
128.   if (entry.value === undefined) return null;
