173. function buildQuestionDescriptors(
174.   form: FillFormEntry,
175.   subjectContext: Partial<
176.     Record<"patientId" | "encounterId" | "facilityId", string>
177.   >,
178.   getStore: GetStore,
179. ): QuestionDescriptor[] {
180.   const store = getStore(form.key);
181.   const responses = store?.get(responsesAtom) ?? {};
182.   const linkIndex = buildLinkIndex(form.questionnaire.questions);
183.   const descriptors: QuestionDescriptor[] = [];
184. 
185.   const walk = (list: Question[], ancestorsEnabled: boolean) => {
186.     for (const question of list) {
187.       const enabled =
188.         ancestorsEnabled &&
189.         isQuestionEnabledInState(question, responses, linkIndex);
190.       if (question.type !== "group") {
191.         const response = responses[question.id];
192.         const isStructured =
193.           question.type === "structured" && !!question.structured_type;
194.         descriptors.push({
195.           id: question.link_id,
196.           text: question.text,
197.           type: question.type,
198.           required: !!question.required,
199.           enabled,
200.           answered: !!response?.values.some(entryHasContent),
201.           ...(question.answer_option?.length
202.             ? { options: question.answer_option.map((option) => option.value) }
203.             : {}),
204.           ...(isStructured
205.             ? {
206.                 structured: structuredSummary(
207.                   question,
208.                   form,
209.                   subjectContext,
210.                   response,
211.                 ),
212.               }
213.             : { value: summarizePlainValue(response) }),
214.         });
215.       }
216.       walk(question.questions ?? [], enabled);
217.     }
218.   };
219.   walk(form.questionnaire.questions, true);
