263. /** The gates shared by both write paths (`setValue`,
264.  *  `applyStructuredEdit`): the question must exist in the resolved form,
265.  *  not be read-only, have a live store entry and a response slot, and be
266.  *  enabled — itself and every ancestor — since `composeBatch` would never
267.  *  submit a disabled question's answer. */
268. function resolveWritableQuestion(
269.   snapshot: SessionSnapshot,
270.   formKey: string | undefined,
271.   questionId: string,
272. ): AssistantResult<WritableQuestion> {
273.   const form = resolveForm(formKey, snapshot.forms);
274.   if (!form) return fail(formNotFoundError(formKey));
275.   const path = findQuestionPath(form.questionnaire.questions, questionId);
276.   if (!path) return fail(noSuchQuestionError(questionId, form));
277.   const question = path[path.length - 1];
278. 
279.   if (question.read_only) {
280.     return fail(`Question "${questionId}" is read-only`);
281.   }
282.   const store = snapshot.getStore(form.key);
283.   if (!store)
284.     return fail(`Form "${form.questionnaire.title}" is not ready yet`);
285.   const previous = store.get(responsesAtom);
286.   const response = previous[question.id];
287.   if (!response) {
288.     return fail(
289.       `Question "${questionId}" is not part of the open form any more`,
290.     );
291.   }
292.   const linkIndex = buildLinkIndex(form.questionnaire.questions);
293.   if (!isPathEnabled(path, previous, linkIndex)) {
294.     return fail(
295.       `Question "${questionId}" is currently disabled by its enable_when conditions and would not be submitted; answer the question it depends on first`,
296.     );
297.   }
298.   return { ok: true, value: { question, store, previous, response } };
299. }
