3. /**
4.  * Structured-write validation: the one place a type's published row
5.  * schema (`model.ts`'s `rowSchema`, wired through the type's registered
6.  * definition) is consulted before an assistant patch is folded into the
7.  * edit log.
8.  *
9.  * SCHEMA AUTHORING NOTE: use `z.object({...}).strict()`, not a bare
10.  * `z.object({...})`. Zod's default silently STRIPS unrecognized keys
11.  * rather than failing `safeParse` — `.strict()` is what actually rejects
12.  * unknown fields. This module parses whatever schema it is given; an
13.  * accepted patch's exact shape is the schema author's responsibility.
14.  */
15. 
16. /** Duck-typed on purpose — `rowSchema` is a field on
17.  *  `StructuredTypeDefinition` (`structured/types.ts`) but not on the
18.  *  `ResolvedStructuredType` view this actually receives; the resolver's
19.  *  spread carries it through at runtime, and reading it structurally
20.  *  picks it up without coupling this module to either type. */
21. interface WithRowSchema {
22.   rowSchema?: z.ZodType;
23. }
24. 
25. export function rowSchemaOf(definition: unknown): z.ZodType | undefined {
26.   if (!definition || typeof definition !== "object") return undefined;
27.   return (definition as WithRowSchema).rowSchema;
28. }
29. 
30. export type StructuredPatchValidationResult =
31.   { ok: true; value: unknown } | { ok: false; error: string };
32. 
33. /**
34.  * Validates one edit's `patch` against its type's published row schema.
35.  *
36.  * FAIL-CLOSED when no schema is published: an unvalidated `unknown`
37.  * patch entering the edit log has no shape guarantee, and a malformed
38.  * row can break that type's editor render for the rest of the session —
39.  * human edits included, since the log is shared. Nothing persists until
40.  * Save, which makes an assistant write safe to LAND in the log; it is
41.  * not a reason to skip validating what lands there.
42.  */
43. export function validateStructuredPatch(
44.   schema: z.ZodType | undefined,
45.   patch: unknown,
46. ): StructuredPatchValidationResult {
47.   if (!schema) {
48.     return {
49.       ok: false,
50.       error:
51.         "This structured type has not published a row validation schema yet, so the assistant cannot safely write to it",
52.     };
53.   }
54.   const parsed = schema.safeParse(patch);
55.   if (!parsed.success) {
56.     const problems = parsed.error.issues
57.       .map((issue) => {
58.         const path = issue.path.join(".");
59.         return path ? `${path}: ${issue.message}` : issue.message;
60.       })
61.       .join("; ");
62.     return { ok: false, error: `Invalid row: ${problems}` };
63.   }
64.   return { ok: true, value: parsed.data };
65. }
