3. /**
4.  * Playwright drivability: exposes each mounted fill session's handle on
5.  * `window`. Gated to test/dev contexts — a real deployment never serves
6.  * from `localhost`, and this repo's Playwright suite always does:
7.  * `playwright.config.ts`'s `webServer` runs `npm run preview`, a genuine
8.  * PRODUCTION build (`import.meta.env.DEV` is `false` there, baked in at
9.  * build time), at `http://localhost:4000`. Gating on `DEV` alone would
10.  * never unlock for Playwright, so the hostname check is the real gate
11.  * for that path; `DEV` stays for `npm run dev`.
12.  *
13.  * `import.meta.env` itself (not just `.DEV`) is read defensively:
14.  * outside Vite — a jsdom `node --test` harness importing this module
15.  * transitively — `import.meta.env` is `undefined`, and
16.  * `import.meta.env.DEV` would throw instead of reading `false`.
17.  */
18. function testBridgeEnabled(): boolean {
19.   if (typeof window === "undefined") return false;
20.   const env = (import.meta as { env?: { DEV?: boolean } }).env;
21.   if (env?.DEV) return true;
22.   return ["localhost", "127.0.0.1"].includes(window.location.hostname);
23. }
24. 
25. export interface FillAssistantTestBridge {
26.   /** Every currently mounted fill session's handle, keyed by a random id
27.    *  minted at mount. A MAP, deliberately — never a single slot: two fill
28.    *  sessions mounted at once must both be reachable, independently, not
29.    *  have the second overwrite the first. */
30.   sessions: Map<string, FillAssistantHandle>;
31.   list(): Array<{ sessionId: string; handle: FillAssistantHandle }>;
32. }
33. 
34. declare global {
35.   interface Window {
36.     __CARE_FILL_ASSISTANT__?: FillAssistantTestBridge;
37.   }
38. }
39. 
40. function bridge(): FillAssistantTestBridge {
41.   if (!window.__CARE_FILL_ASSISTANT__) {
42.     const sessions = new Map<string, FillAssistantHandle>();
43.     window.__CARE_FILL_ASSISTANT__ = {
44.       sessions,
45.       list: () =>
46.         Array.from(sessions.entries()).map(([sessionId, handle]) => ({
47.           sessionId,
48.           handle,
49.         })),
50.     };
51.   }
52.   return window.__CARE_FILL_ASSISTANT__;
53. }
54. 
55. /**
56.  * Registers one session's handle on `window` for the lifetime of its
57.  * mount. A no-op (with a no-op cleanup) outside the test/dev gate — the
58.  * bridge object itself never exists in a real deployment, so there is
59.  * nothing on `window` for a production page to leak.
60.  */
61. export function registerTestBridgeSession(
62.   handle: FillAssistantHandle,
63. ): () => void {
64.   if (!testBridgeEnabled()) return () => {};
65.   const sessionId = crypto.randomUUID();
66.   bridge().sessions.set(sessionId, handle);
67.   return () => {
68.     // Re-reads `window.__CARE_FILL_ASSISTANT__` rather than closing over
69.     // the earlier `bridge()` call's object: harmless either way today
70.     // (the bridge object is created once and never replaced), but keeps
71.     // this cleanup correct even if that ever changes.
72.     window.__CARE_FILL_ASSISTANT__?.sessions.delete(sessionId);
73.   };
74. }
