62. export async function toRequests(
63.   edits: readonly StructuredEdit<TimeOfDeathRow>[],
64.   { patientId, questionId }: StructuredRequestContext,
65. ): Promise<StructuredBatchEntry[]> {
66.   // `subjects` is patient/encounter, so a patient is in scope in practice;
67.   // narrowed rather than asserted because the context type is optional for
68.   // plugin types on a resource subject.
69.   if (!patientId) return [];
70.   // `removes` is ignored: no delete endpoint and no soft-delete marker —
71.   // the editor's add-then-clear annihilates in the log, so a surviving
72.   // `remove` can only be a malformed draft's stray edit.
73.   const { creates, updates } = resolveChanges(edits, {});
74.   // Singleton: collapse to AT MOST ONE request — a malformed draft could
75.   // carry two rowIds, and this must never PUT the same patient endpoint
76.   // twice in one batch. Blanks are filtered OUT before taking the last
77.   // entry so whatever `projectValues` shows as the answered row is exactly
78.   // what this differ sends. NOT log order, despite `[...creates,
79.   // ...updates]` reading like it: `resolveChanges` groups by set, so
80.   // `.at(-1)` picks the last UPDATE if any exist, else the last CREATE —
81.   // harmless for a well-formed one-rowId log, arbitrary-but-deterministic
82.   // for a malformed one.
83.   const row = [...creates, ...updates].filter((r) => !isEmptyRow(r)).at(-1);
