170. /**
171.  * The carry-over decision, as a pure function: given the CURRENT
172.  * questionnaire's questions and a stored draft's responses, returns the
173.  * merged response map (seeded fresh, then overlaid per the rules below)
174.  * plus every answer that could not be carried over, with a machine reason
175.  * the restore bar can translate and label.
176.  *
177.  * CARRY-OVER RULES:
178.  *  - The question id no longer exists in the current tree -> DROPPED
179.  *    (`question_removed`), labeled by the stored response's `link_id` —
180.  *    no live `Question` remains to read a label from.
181.  *  - The question exists but the recorded value's shape doesn't fit what
182.  *    the CURRENT question type can produce (`EXPECTED_VALUE_TYPES`) ->
183.  *    DROPPED (`type_changed`), the whole response — a type change
184.  *    invalidates the answer's meaning, not just its encoding.
185.  *  - A structured question whose `structured_type` differs from what the
186.  *    draft recorded -> DROPPED (`type_changed`) at this same whole-
187.  *    response level, before `useStructuredRows` (per-`rowId` baseline
188.  *    reconciliation) ever mounts. A matching type restores its edit log
189.  *    verbatim; `useStructuredRows`' `droppedEdits` channel then names any
190.  *    individual row a refetched baseline no longer has — this function
191.  *    only decides whether the section applies at all.
192.  *  - Choice/quantity: entries whose stored value/coding no longer matches
193.  *    a `answer_option`/fixed-`unit` the current question declares are
194.  *    filtered out of that one response -> reported (`option_removed`);
195.  *    whatever remains restores. See `choiceValueStillAvailable` for the
196.  *    valueset-backed scope limitation.
197.  *  - Everything else restores unchanged.
198.  *
199.  * A response with nothing worth restoring (`draftResponseHasContent`
200.  * false) is never reported as dropped — there is nothing lost to name.
201.  *
202.  * `questions` seeds the base via `initializeResponses`, so a question the
203.  * draft never mentions (added since, or simply unanswered) still gets its
204.  * normal fresh/initial response.
205.  */
206. export function mergeDraftResponses(
207.   questions: Question[],
208.   draft: Record<string, QuestionnaireResponse>,
209. ): DraftMergeResult {
210.   const byId = indexQuestions(questions);
211.   const merged = initializeResponses(questions);
212.   const dropped: DroppedDraftAnswer[] = [];
213. 
214.   for (const [id, response] of Object.entries(draft)) {
215.     const fresh = byId.get(id);
216. 
217.     if (!fresh) {
218.       if (draftResponseHasContent(response)) {
219.         dropped.push({
220.           questionId: id,
221.           label: response.link_id || id,
222.           reason: "question_removed",
223.         });
224.       }
225.       continue;
226.     }
227. 
228.     // Structured: whole-response gate on structured_type. Per-row
229.     // reconciliation against the refetched baseline is
230.     // `useStructuredRows`'s job (droppedEdits), not this function's.
231.     if (fresh.type === "structured" || response.structured_type) {
232.       if (fresh.structured_type !== response.structured_type) {
233.         if (draftResponseHasContent(response)) {
234.           dropped.push({
235.             questionId: id,
236.             label: fresh.text,
237.             reason: "type_changed",
238.           });
239.         }
240.         continue;
241.       }
242.       merged[id] = { ...response, link_id: fresh.link_id };
243.       continue;
244.     }
245. 
246.     // Plain question: the recorded VALUE SHAPE must still fit what the
247.     // current question type can produce.
248.     const shapeCompatible = response.values.every((entry) =>
249.       valueTypeMatchesQuestion(fresh, entry),
250.     );
251.     if (!shapeCompatible) {
252.       if (draftResponseHasContent(response)) {
253.         dropped.push({
254.           questionId: id,
255.           label: fresh.text,
256.           reason: "type_changed",
257.         });
258.       }
259.       continue;
260.     }
261. 
262.     const { kept, anyDropped } = filterAvailableEntries(fresh, response.values);
263.     if (anyDropped) {
264.       dropped.push({
265.         questionId: id,
266.         label: fresh.text,
267.         reason: "option_removed",
268.       });
269.     }
270. 
271.     merged[id] = {
272.       ...response,
273.       link_id: fresh.link_id,
274.       structured_type: fresh.structured_type ?? null,
275.       values: kept,
276.     };
277.   }
278. 
279.   return { responses: merged, dropped };
280. }
281.

1. /**
2.  * The dependency-free half of the local fill-draft layer: key prefix,
3.  * expiry rule and the sweeps. signOut, the app-update path and the
4.  * post-auth-success boundary import THIS module — never `fillDraftStore`,
5.  * whose registry import would drag every structured component into their
6.  * chunks.
7.  *
8.  * Lifecycle: a fresh login by a DIFFERENT user sweeps every OTHER user's
9.  * drafts (`clearOtherUsersFillDrafts`) — the just-authenticated user's own
10.  * drafts survive, since re-login by the same account is the crash/session-
11.  * expiry recovery this layer exists for. signOut and an app update sweep
12.  * EVERYTHING (`clearQuestionnaireFillDrafts`) — there is no "same user"
13.  * exception once a session is deliberately ended. Expired/corrupt drafts,
14.  * for any user, are swept once at boot regardless of auth outcome
15.  * (`sweepExpiredFillDrafts`).
16.  */
17. export const FILL_DRAFT_PREFIX = "care_qn_fill_draft--";
18. 
19. const TTL_MS = 24 * 60 * 60 * 1000;
20. 
21. export function isFillDraftExpired(savedAt: string): boolean {
22.   const saved = new Date(savedAt).getTime();
23.   return isNaN(saved) || Date.now() - saved > TTL_MS;
24. }
25. 
26. /** Prefix sweep — registered at signOut and app update so draft data
27.  *  never outlives a deliberately-ended session. */
28. export function clearQuestionnaireFillDrafts(): void {
29.   for (const key of Object.keys(localStorage)) {
30.     if (key.startsWith(FILL_DRAFT_PREFIX)) localStorage.removeItem(key);
31.   }
32. }
33. 
34. /**
35.  * Prefix sweep scoped to every OTHER user — registered at the post-auth-
36.  * success boundary (JWT sign-in and MFA verification) so a login by a
37.  * DIFFERENT account on a shared device gets a clean slate, while the
38.  * just-authenticated user's own draft (e.g. one left at the login form by
39.  * a session expiry) survives re-login. A key whose userId segment cannot
40.  * be parsed is treated as untrusted and removed, same as a corrupt entry.
41.  */
42. export function clearOtherUsersFillDrafts(currentUserId: string): void {
43.   for (const key of Object.keys(localStorage)) {
44.     if (!key.startsWith(FILL_DRAFT_PREFIX)) continue;
45.     const userId = key.slice(FILL_DRAFT_PREFIX.length).split("--")[0];
46.     if (!userId || userId !== currentUserId) {
47.       localStorage.removeItem(key);
48.     }
49.   }
50. }
51. 
52. /** Drop expired/corrupt drafts (any user) — run on fill page mount and at
53.  *  provider boot, independent of auth outcome. */
54. export function sweepExpiredFillDrafts(): void {
55.   for (const key of Object.keys(localStorage)) {
56.     if (!key.startsWith(FILL_DRAFT_PREFIX)) continue;
57.     try {
58.       const draft = JSON.parse(localStorage.getItem(key) ?? "") as {
59.         savedAt?: string;
60.       };
61.       if (!draft.savedAt || isFillDraftExpired(draft.savedAt)) {
62.         localStorage.removeItem(key);
63.       }
64.     } catch {
65.       localStorage.removeItem(key);
66.     }
67.   }
68. }
69.

1. import { entryHasContent } from "@/components/QuestionnaireV2/form/engine/store";
2. import { resolveStructuredType } from "@/components/QuestionnaireV2/structured/registry";
3. 
4. import type { QuestionnaireResponse } from "@/types/questionnaire/form";
5. import type { Question } from "@/types/questionnaire/question";
6. import type { QuestionnaireRead } from "@/types/questionnaire/questionnaire";
7. 
8. import type { DroppedDraftAnswer } from "./draftMerge";
9. import { draftResponseHasContent, mergeDraftResponses } from "./draftMerge";
10. import { FILL_DRAFT_PREFIX, isFillDraftExpired } from "./fillDraftCache";
11. 
12. /**
13.  * Local fill drafts — the crash/reload safety net. Draft data lives in
14.  * localStorage only under this prefix, scoped per user + subject + entry
15.  * questionnaire, TTL-bounded, and swept on an OTHER user's login, on
16.  * signOut and on app update — every eviction hook is deliberate; a new
17.  * session boundary must join the sweep list. Expired drafts are swept at
18.  * boot regardless of auth outcome. A user's OWN drafts deliberately
19.  * survive their own re-login — that is the crash/session-expiry recovery
20.  * this layer exists for, not a bug (see `fillDraftCache.ts`).
21.  *
22.  * One key holds the WHOLE fill session: the route-mounted questionnaire
23.  * plus every questionnaire added to the same submission.
24.  */
25. const SCHEMA_VERSION = 2;
26. 
27. export interface FillDraftScope {
28.   userId: string;
29.   /** encounterId when encounter-bound, else patientId. */
30.   subjectKey: string;
31.   /** The route-mounted questionnaire's id — the session key. */
32.   entryQuestionnaireId: string;
33. }
34. 
35. export interface DraftFormSnapshot {
36.   questionnaireId: string;
37.   /** `QuestionnaireRead.version` — a version bump invalidates this form
38.    *  (the read spec exposes no modified_date yet). */
39.   questionnaireVersion: string;
40.   /** The questionnaire's title as it read when the draft was written —
41.    *  the only human name available when a resume can no longer FETCH the
42.    *  questionnaire. Optional because v2 drafts written before this field
43.    *  existed are still valid; every reader must fall back. */
44.   title?: string;
45.   responses: Record<string, QuestionnaireResponse>;
46.   structuredSkipped: boolean;
47. }
48. 
49. interface StoredFillDraft {
50.   schemaVersion: number;
51.   savedAt: string;
52.   userId: string;
53.   subjectKey: string;
54.   entryQuestionnaireId: string;
55.   forms: DraftFormSnapshot[];
56. }
57. 
58. export interface LoadedFillDraft {
59.   forms: DraftFormSnapshot[];
60.   savedAt: string;
61.   /** True when the saved session had structured answers the draft could
62.    *  not carry (draftPolicy "exclude") — the restore bar says so. */
63.   structuredSkipped: boolean;
64.   /**
65.    * The restore bar's drop notice, precomputed for the PRIMARY form at
66.    * LOAD time (before the clinician even decides Resume vs Discard) —
67.    * `mergeDraftResponses` run against the questionnaire's CURRENT
68.    * questions. Empty when nothing would be lost, including the ordinary
69.    * case where the questionnaire never changed at all. Non-primary
70.    * (added) forms are merged later, when the host re-fetches them on
71.    * resume (`useFillSessionForms.ts`), and are not represented here.
72.    */
73.   dropped: DroppedDraftAnswer[];
74. }
75. 
76. function draftKey(scope: FillDraftScope): string {
77.   return `${FILL_DRAFT_PREFIX}${scope.userId}--${scope.subjectKey}--${scope.entryQuestionnaireId}`;
78. }
79. 
80. /**
81.  * One response as a draft stores it.
82.  *
83.  * A resolved structured question keeps its EDIT LOG and drops its
84.  * PROJECTION: those rows are the query layer's copy of the server's
85.  * data — restoring stale clinical rows and re-upserting them could
86.  * clobber edits made elsewhere. Edits are small, JSON-safe and meaningful
87.  * without the baseline (each carries its whole row), so a restore
88.  * re-fetches the rows and re-projects the log on top.
89.  *
90.  * Everything else — plain answers, an unresolvable structured type — is
91.  * stored verbatim (same object reference): this function is a no-op for
92.  * every response that isn't a resolved structured question.
93.  */
94. export function draftResponseForStorage(
95.   response: QuestionnaireResponse,
96. ): QuestionnaireResponse {
97.   if (!response.structured_type) return response;
98.   const resolved = resolveStructuredType(response.structured_type);
99.   if (!resolved) return response;
100.   return { ...response, values: [] };
101. }
102. 
103. /** Is this response one the draft deliberately leaves behind? An
104.  *  unresolvable structured type (its plugin isn't loaded) counts as
105.  *  "exclude": nothing here knows whether its values are serializable, and
106.  *  a restore would hand them to a component that may never come back.
107.  *  `files` is the only legitimate "exclude" among resolvable types (raw
108.  *  `File` objects cannot round-trip through JSON). */
109. function isDraftExcluded(response: QuestionnaireResponse): boolean {
110.   if (!response.structured_type) return false;
111.   const resolved = resolveStructuredType(response.structured_type);
112.   return !resolved || resolved.draftPolicy === "exclude";
113. }
114. 
115. /**
116.  * Split responses into draft-safe entries and skipped structured content.
117.  * `isDraftExcluded` responses never enter the draft — restoring stale
118.  * clinical rows and re-upserting them could clobber edits made elsewhere.
119.  * A "safe" entry still goes through `draftResponseForStorage`, which
120.  * strips a resolved structured question's projection down to its edit
121.  * log before it is stored.
122.  */
123. function partitionForDraft(responses: Record<string, QuestionnaireResponse>): {
124.   safe: Record<string, QuestionnaireResponse>;
125.   structuredSkipped: boolean;
126. } {
127.   const safe: Record<string, QuestionnaireResponse> = {};
128.   let structuredSkipped = false;
129.   for (const [id, response] of Object.entries(responses)) {
130.     if (isDraftExcluded(response)) {
131.       if (response.values.some(entryHasContent)) structuredSkipped = true;
132.       continue;
133.     }
134.     safe[id] = draftResponseForStorage(response);
135.   }
136.   return { safe, structuredSkipped };
137. }
138. 
139. /**
140.  * Overlay the draft-excluded structured entries a store already holds onto
141.  * a record that is about to REPLACE it.
142.  *
143.  * Resume and Discard both swap a form's whole responses record. Structured
144.  * types with `draftPolicy: "exclude"` are by definition not in the draft,
145.  * and the adapted widgets seed them once from a server prefetch in a mount
146.  * effect that never re-runs — so a plain replacement blanks the patient's
147.  * existing allergies/medications/diagnoses on screen, and re-entering them
148.  * upserts DUPLICATE clinical records. The live values are the only copy;
149.  * they carry across untouched.
150.  */
151. export function preserveExcludedStructured(
152.   current: Record<string, QuestionnaireResponse>,
153.   next: Record<string, QuestionnaireResponse>,
154. ): Record<string, QuestionnaireResponse> {
155.   const merged = { ...next };
156.   for (const [id, response] of Object.entries(current)) {
157.     if (!isDraftExcluded(response)) continue;
158.     const fresh = merged[id];
159.     // Same guard the draft overlay uses: only where the question still
160.     // exists with the same structured_type.
161.     if (fresh && fresh.structured_type === response.structured_type) {
162.       merged[id] = response;
163.     }
164.   }
165.   return merged;
166. }
167. 
168. /**
169.  * The creation-time merge rule for resume paths: draft entries overlay
170.  * the fresh seed per `draftMerge.ts`'s compatibility rules — restoring
171.  * where the question still exists with a shape-compatible type/option,
172.  * dropping what does not. A thin wrapper for call sites that don't
173.  * surface the drop list (`useFillAutosave.ts`'s primary-form resume,
174.  * whose drops `loadFillDraft` already precomputed at detection time, and
175.  * `useFillSessionForms.ts`'s added-form paths).
176.  */
177. export function mergeDraftIntoSeed(
178.   questions: Question[],
179.   draft: Record<string, QuestionnaireResponse>,
180. ): Record<string, QuestionnaireResponse> {
181.   return mergeDraftResponses(questions, draft).responses;
182. }
183. 
184. /** The live working state of one form, as the fill host reads it out of
185.  *  that form's store. */
186. export interface FillSessionFormState {
187.   questionnaire: QuestionnaireRead;
188.   responses: Record<string, QuestionnaireResponse>;
189. }
190. 
191. function snapshotSession(forms: FillSessionFormState[]): {
192.   snapshots: DraftFormSnapshot[];
193.   anyContent: boolean;
194. } {
195.   const snapshots: DraftFormSnapshot[] = [];
196.   let anyContent = false;
197.   for (const form of forms) {
198.     const { safe, structuredSkipped } = partitionForDraft(form.responses);
199.     const hasContent = Object.values(safe).some(draftResponseHasContent);
200.     // `structuredSkipped` ANNOTATES a draft (the restore bar warns about
201.     // it); it never creates one on its own. Adapted structured widgets
202.     // seed prefetched server rows into the store in mount effects, so
203.     // counting the flag as content wrote a phantom draft for a session the
204.     // clinician never touched — and let that phantom overwrite a real
205.     // stored draft on the very next visit.
206.     if (hasContent) anyContent = true;
207.     snapshots.push({
208.       questionnaireId: form.questionnaire.id,
209.       questionnaireVersion: String(form.questionnaire.version),
210.       title: form.questionnaire.title,
211.       responses: safe,
212.       structuredSkipped,
213.     });
214.   }
215.   return { snapshots, anyContent };
216. }
217. 
218. /**
219.  * A stable fingerprint of everything a draft WOULD store for this session:
220.  * the draft-safe partition of every form's responses.
221.  *
222.  * Autosave compares it against the last value it saw, so a structured
223.  * widget writing its prefetched server rows (draftPolicy "exclude" —
224.  * never part of a draft) cannot register as a clinician edit; otherwise
225.  * merely opening a clinical form would light the Draft chip, arm the
226.  * unsaved-changes prompt and persist a draft nobody asked for.
227.  *
228.  * `draftPolicy: "exclude"` types stay out of the signature entirely
229.  * (excluded by `partitionForDraft`). Every other structured type is in it
230.  * as its edit log with the projection stripped
231.  * (`draftResponseForStorage`) — a baseline refetch (which only ever
232.  * rewrites `values`) is invisible here, while a clinician's edit (which
233.  * rewrites `edits`) is visible.
234.  */
235. export function safeSessionSignature(forms: FillSessionFormState[]): string {
236.   return JSON.stringify(
237.     forms.map((form) => [
238.       form.questionnaire.id,
239.       partitionForDraft(form.responses).safe,
240.     ]),
241.   );
242. }
243. 
244. /** Persist the working state of every form in the session. A session with
245.  *  no draft-SAFE content removes the key instead (never store empty
246.  *  drafts — FiltersCache's clean() convention); draft-excluded structured
247.  *  answers alone are not content, only an annotation on a draft some
248.  *  plain answer already earned. */
249. export function saveFillDraft(
250.   scope: FillDraftScope,
251.   forms: FillSessionFormState[],
252.   /** Snapshots that belong to this draft but are NOT in the live session:
253.    *  a resume whose re-fetch of an added questionnaire failed. They ride
254.    *  through verbatim, because the alternative is that one transient
255.    *  network error during Resume silently and permanently deletes that
256.    *  form's drafted answers. */
257.   retained: DraftFormSnapshot[] = [],
258. ): void {
259.   const { snapshots, anyContent } = snapshotSession(forms);
260.   const live = new Set(snapshots.map((snapshot) => snapshot.questionnaireId));
261.   const carried = retained.filter(
262.     (snapshot) => !live.has(snapshot.questionnaireId),
263.   );
264.   const carriedContent = carried.some((snapshot) =>
265.     Object.values(snapshot.responses).some(draftResponseHasContent),
266.   );
267.   if (!anyContent && !carriedContent) {
268.     clearFillDraft(scope);
269.     return;
270.   }
271.   const draft: StoredFillDraft = {
272.     schemaVersion: SCHEMA_VERSION,
273.     savedAt: new Date().toISOString(),
274.     userId: scope.userId,
275.     subjectKey: scope.subjectKey,
276.     entryQuestionnaireId: scope.entryQuestionnaireId,
277.     forms: [...snapshots, ...carried],
278.   };
279.   try {
280.     localStorage.setItem(draftKey(scope), JSON.stringify(draft));
281.   } catch {
282.     // Quota exceeded / storage disabled — autosave is best-effort.
283.   }
284. }
285. 
286. /** JSON round-trips Dates to ISO strings; date/dateTime entries revive to
287.  *  Date objects so the inputs' discriminant checks keep working. Exported
288.  *  for the server-draft (`?continue_draft=`) restore path, whose dump went
289.  *  through the same JSON flattening. */
290. export function reviveDraftResponses(
291.   responses: Record<string, QuestionnaireResponse>,
292. ): Record<string, QuestionnaireResponse> {
293.   for (const response of Object.values(responses)) {
294.     // Server dumps are untyped blobs — a `values`-less entry is possible
295.     // and must not throw the whole encounter overview.
296.     for (const entry of response.values ?? []) {
297.       // Fresh from JSON.parse the declared Date is actually a string —
298.       // read through `unknown` at this one boundary.
299.       const raw = (entry as { value?: unknown }).value;
300.       if (
301.         (entry.type === "date" || entry.type === "dateTime") &&
302.         typeof raw === "string"
303.       ) {
304.         const revived = new Date(raw);
305.         entry.value = isNaN(revived.getTime()) ? undefined : revived;
306.       }
307.     }
308.   }
309.   return responses;
310. }
311. 
312. /**
313.  * Load the draft session for this exact scope; anything mismatched,
314.  * expired or corrupt is removed and reported absent.
315.  *
316.  * A primary-form VERSION MISMATCH does not reject the draft: the
317.  * compatibility-aware merge (`draftMerge.ts`'s `mergeDraftResponses`, run
318.  * here against the CURRENT `questions`) restores what still fits and
319.  * precomputes the restore bar's notice (see `dropped` on
320.  * {@link LoadedFillDraft}). The checks below ARE wholesale-reject-worthy:
321.  * they identify a draft belonging to a different identity entirely (wrong
322.  * user/subject/entry questionnaire), expired, or unparseable — not "the
323.  * same session's questionnaire changed underneath it". v1 drafts fail the
324.  * `schemaVersion` check and are removed; that is the whole migration.
325.  *
326.  * Only the PRIMARY form's `dropped` notice is computed here — added forms
327.  * are merged (and version-checked) when the host re-fetches them on
328.  * resume (`useFillSessionForms.ts`'s `onResumeAddedForms`).
329.  */
330. export function loadFillDraft(
331.   scope: FillDraftScope,
332.   questions: Question[],
333. ): LoadedFillDraft | undefined {
334.   const key = draftKey(scope);
335.   const raw = localStorage.getItem(key);
336.   if (!raw) return undefined;
337.   try {
338.     const draft = JSON.parse(raw) as StoredFillDraft;
339.     const primary = draft.forms?.find(
340.       (form) => form.questionnaireId === scope.entryQuestionnaireId,
341.     );
342.     if (
343.       draft.schemaVersion !== SCHEMA_VERSION ||
344.       draft.userId !== scope.userId ||
345.       draft.subjectKey !== scope.subjectKey ||
346.       draft.entryQuestionnaireId !== scope.entryQuestionnaireId ||
347.       isFillDraftExpired(draft.savedAt) ||
348.       !primary
349.     ) {
350.       localStorage.removeItem(key);
351.       return undefined;
352.     }
353.     for (const form of draft.forms) {
354.       form.responses = reviveDraftResponses(form.responses);
355.     }
356.     const { dropped } = mergeDraftResponses(questions, primary.responses);
357.     return {
358.       forms: draft.forms,
359.       savedAt: draft.savedAt,
360.       structuredSkipped: draft.forms.some((form) => form.structuredSkipped),
361.       dropped,
362.     };
363.   } catch {
364.     localStorage.removeItem(key);
365.     return undefined;
366.   }
367. }
368. 
369. export function clearFillDraft(scope: FillDraftScope): void {
370.   localStorage.removeItem(draftKey(scope));
371. }
372.

1. import type { Question } from "@/types/questionnaire/question";
2. 
3. /**
4.  * What `unsupportedDraftStructuredTypes` needs to know about a resolved
5.  * structured type — a structural subset of `ResolvedStructuredType`
6.  * (`structured/registry.ts`), duck-typed rather than imported so this
7.  * module stays import-free of `registry.ts`, which transitively imports
8.  * every core structured definition's real component tree (CSS, UI
9.  * libraries) and cannot run under the plain `node --test` harness (the
10.  * same constraint `fill/submit/composeStructured.ts` documents).
11.  * `useSaveServerDraft.ts` passes the real `resolveStructuredType` as the
12.  * `resolve` parameter; a test passes a fake one.
13.  */
14. export interface DraftResolvableStructuredType {
15.   draftPolicy: "serialize" | "exclude";
16. }
17. 
18. /**
19.  * The structured questions in this tree that a SERVER draft cannot
20.  * faithfully carry, by `structured_type` (or the `"<untyped>"`
21.  * placeholder for a `type: "structured"` question with no
22.  * `structured_type` at all).
23.  *
24.  * Every structured type dumps its EDIT LOG, which is user intent alone
25.  * and re-projects onto a freshly fetched baseline — so a server draft
26.  * can carry it faithfully, except where the values cannot round-trip at
27.  * all (`draftPolicy: "exclude"` — `files`), and except for a type this
28.  * deployment cannot resolve. An untyped structured question also blocks:
29.  * `resolve` is never called without a type string, so the question
30.  * reports under the `"<untyped>"` placeholder.
31.  */
32. export function unsupportedDraftStructuredTypes(
33.   questions: Question[],
34.   resolve: (type: string) => DraftResolvableStructuredType | undefined,
35. ): string[] {
36.   const blocking: string[] = [];
37.   const walk = (list: Question[]) => {
38.     for (const question of list) {
39.       if (question.type === "group") {
40.         walk(question.questions ?? []);
41.         continue;
42.       }
43.       if (question.type !== "structured") continue;
44.       const resolved = question.structured_type
45.         ? resolve(question.structured_type)
46.         : undefined;
47.       if (!resolved || resolved.draftPolicy === "exclude") {
48.         blocking.push(question.structured_type ?? "<untyped>");
49.       }
50.     }
51.   };
52.   walk(questions);
53.   return blocking;
54. }
55.

260.   rowId: string;
261.   fieldKey: RequiredServiceRequestField;
262. }
263. 
264. /** Pure predicate — `definitions/serviceRequest.tsx` is the only place a
265.  *  miss becomes a translated, row_id-keyed error. A `remove` edit is never
266.  *  reported: the row is on its way out, not something left to fix. */
267. export function requiredServiceRequestFieldMisses(
268.   edits: readonly StructuredEdit<ServiceRequestRow>[],
269. ): RequiredFieldMiss[] {
270.   const misses: RequiredFieldMiss[] = [];
271.   for (const edit of edits) {
272.     if (edit.op === "remove") continue;
273.     for (const fieldKey of REQUIRED_SERVICE_REQUEST_FIELDS) {
274.       if (!edit.patch.service_request[fieldKey]) {
275.         misses.push({ rowId: edit.rowId, fieldKey });
276.       }
277.     }
278.   }
279.   return misses;
280. }
