1. import { useCallback, useEffect, useRef, useState } from "react";
2. import { flushSync } from "react-dom";
3. 
4. import { responsesAtom } from "@/components/QuestionnaireV2/form/engine/store";
5. 
6. import type { FillFormEntry } from "@/components/QuestionnaireV2/fill/formSession";
7. import type { FormStore } from "@/components/QuestionnaireV2/fill/StoreRegistrar";
8. 
9. import type {
10.   DraftFormSnapshot,
11.   FillDraftScope,
12.   FillSessionFormState,
13.   LoadedFillDraft,
14. } from "./fillDraftStore";
15. import {
16.   clearFillDraft,
17.   mergeDraftIntoSeed,
18.   preserveExcludedStructured,
19.   safeSessionSignature,
20.   saveFillDraft,
21. } from "./fillDraftStore";
22. 
23. const AUTOSAVE_DEBOUNCE_MS = 1500;
24. 
25. /** The draft-safe signature for ONE form — `safeSessionSignature` scoped
26.  *  to a single-element input, so the per-form fingerprint is exactly what
27.  *  this form contributes to the whole-session signature (one partitioning
28.  *  rule, never two). */
29. function formSignature(form: FillFormEntry, store: FormStore): string {
30.   return safeSessionSignature([
31.     { questionnaire: form.questionnaire, responses: store.get(responsesAtom) },
32.   ]);
33. }
34. 
35. interface UseFillSessionAutosaveArgs {
36.   /** This session's draft key — undefined only before the questionnaire
37.    *  loads. Supplied even in modes that never WRITE a local draft: a
38.    *  successful submit must still clear a sibling draft stored under the
39.    *  same key by an earlier plain session. */
40.   scope: FillDraftScope | undefined;
41.   /** false while resuming a SERVER draft: the server copy is authoritative
42.    *  there, so nothing persists locally. Dirty tracking stays on either
43.    *  way — the unsaved-changes prompt and the Draft chip are about the
44.    *  clinician's un-submitted edits, not about where the bytes live. */
45.   persistLocally?: boolean;
46.   /** Every questionnaire in the session, primary first. */
47.   forms: FillFormEntry[];
48.   getStore: (key: string) => FormStore | undefined;
49.   /** Bumped by the host whenever a StoreRegistrar (un)registers. */
50.   storesVersion: number;
51.   /** The draft this page instance detected, if any. */
52.   restoredDraft: LoadedFillDraft | undefined;
53.   /** Snapshots the host could not turn back into live forms (a resume
54.    *  whose re-fetch failed). They stay in the persisted draft so a
55.    *  transient error cannot destroy their answers. */
56.   retainedSnapshots?: DraftFormSnapshot[];
57.   /** Resume path for forms beyond the primary: the host re-adds them
58.    *  (fetch by id, version-check, seed via initialResponses). */
59.   onResumeAddedForms: (snapshots: DraftFormSnapshot[]) => void;
60. }
61. 
62. /**
63.  * The local autosave engine for a whole fill session. Lives OUTSIDE the
64.  * form providers: it reaches each form's instance store through the
65.  * host's registry, subscribes to all of them behind one shared debounce,
66.  * flushes on pagehide/unmount so quick closes keep the last keystrokes,
67.  * and exposes the state the chrome renders (Draft chip, restore bar).
68.  *
69.  * `discardRestoredDraft` clears the stored draft and nothing else — what
70.  * is on screen is this session's own work (a draft only reaches the
71.  * stores through Resume), so the affordance destroys exactly the bytes
72.  * it names.
73.  */
74. export function useFillSessionAutosave({
75.   scope,
76.   persistLocally = true,
77.   forms,
78.   getStore,
79.   storesVersion,
80.   restoredDraft,
81.   retainedSnapshots,
82.   onResumeAddedForms,
83. }: UseFillSessionAutosaveArgs) {
84.   const [dirty, setDirty] = useState(false);
85.   const [restoreDismissed, setRestoreDismissed] = useState(false);
86. 
87.   // The subscription effect reads these without re-subscribing.
88.   const scopeRef = useRef(scope);
89.   scopeRef.current = scope;
90.   const persistRef = useRef(persistLocally);
91.   persistRef.current = persistLocally;
92.   const retainedRef = useRef(retainedSnapshots);
93.   retainedRef.current = retainedSnapshots;
94.   // Set on successful submit: the draft served its purpose, so neither the
95.   // pending debounce nor the unmount/pagehide flush may re-save it.
96.   const finishedRef = useRef(false);
97.   // Read by resumeRestoredDraft, which only ever fires from an event
98.   // handler well after mount.
99.   const restoredDraftRef = useRef(restoredDraft);
100.   restoredDraftRef.current = restoredDraft;
101.   // A detected draft the clinician has neither resumed nor discarded is
102.   // still theirs to decide about — see persistNow.
103.   const restorePendingRef = useRef(false);
104.   restorePendingRef.current = !!restoredDraft && !restoreDismissed;
105. 
106.   const scopeKey = scope
107.     ? `${scope.userId}--${scope.subjectKey}--${scope.entryQuestionnaireId}`
108.     : undefined;
109. 
110.   /** One snapshot per REGISTERED form — a form whose section hasn't
111.    *  mounted yet simply doesn't contribute. */
112.   const snapshotAll = useCallback((): FillSessionFormState[] => {
113.     const snapshots: FillSessionFormState[] = [];
114.     for (const form of forms) {
115.       const store = getStore(form.key);
116.       if (!store) continue;
117.       snapshots.push({
118.         questionnaire: form.questionnaire,
119.         responses: store.get(responsesAtom),
120.       });
121.     }
122.     return snapshots;
123.   }, [forms, getStore]);
124. 
125.   /**
126.    * Write the whole session to its one draft entry. Never runs after a
127.    * successful submit, and never while `persistLocally` is off.
128.    *
129.    * While the restore prompt is still un-acted NOTHING persists: the
130.    * stored draft is the clinician's to accept or discard, and any write
131.    * from this session would either overwrite it (a structured prefetch, a
132.    * keystroke) or — via `saveFillDraft`'s clear-on-empty branch — delete
133.    * it outright.
134.    */
135.   const persistNow = useCallback(() => {
136.     const current = scopeRef.current;
137.     if (!current || !persistRef.current || finishedRef.current) return;
138.     if (restorePendingRef.current) return;
139.     saveFillDraft(current, snapshotAll(), retainedRef.current);
140.   }, [snapshotAll]);
141. 
142.   /**
143.    * The session SHAPE changed (a form was added or removed) or a store
144.    * (un)registered — persist now. The debounce cannot cover this: on an
145.    * update React runs the previous effect's cleanup BEFORE the new
146.    * sections' StoreRegistrars register, so that flush would write a
147.    * snapshot missing the just-added forms and silently shrink the stored
148.    * draft (the Resume path re-adds drafted forms exactly this way).
149.    * Gated on `dirty`, because an untouched session is empty and an empty
150.    * save takes `saveFillDraft`'s clear-on-empty branch.
151.    */
152.   useEffect(() => {
153.     if (!scopeKey || !persistLocally || !dirty) return;
154.     persistNow();
155.   }, [
156.     scopeKey,
157.     persistLocally,
158.     dirty,
159.     storesVersion,
160.     retainedSnapshots,
161.     persistNow,
162.   ]);
163. 
164.   // Not gated on `scopeKey`/`persistLocally`: dirty tracking is what arms
165.   // the unsaved-changes prompt and the Draft chip, and a session resuming
166.   // a SERVER draft needs both even though it writes no local draft.
167.   // `persistNow` is the thing that stands down, not the subscription.
168.   useEffect(() => {
169.     let timer: ReturnType<typeof setTimeout> | undefined;
170. 
171.     const flush = () => {
172.       if (timer === undefined) return;
173.       clearTimeout(timer);
174.       timer = undefined;
175.       persistNow();
176.     };
177. 
178.     // Per-form signature cache, keyed by form.key. A keystroke only ever
179.     // changes the ONE store that fired, so comparing just that form's own
180.     // cached entry is sufficient — no other form's signature could have
181.     // changed, so there is nothing to gain from joining them into a
182.     // session-wide value.
183.     //
184.     // Rebuilt from scratch on every (re)run of this effect — a form
185.     // add/remove or a store (un)registration bumps `storesVersion`, which
186.     // is a dependency below — by iterating the CURRENT `forms`/`getStore`.
187.     // A form no longer in that iteration simply never gets an entry, so a
188.     // removed form's stale signature can never survive to be compared
189.     // against again.
190.     //
191.     // Whatever is already in the stores when this is built is the
192.     // baseline, not an edit — this is where the structured widgets'
193.     // prefetched server rows sit.
194.     const formSignatures = new Map<string, string>();
195.     for (const form of forms) {
196.       const store = getStore(form.key);
197.       if (!store) continue;
198.       formSignatures.set(form.key, formSignature(form, store));
199.     }
200. 
201.     // One shared debounce across every form of the session — the draft is
202.     // one localStorage entry, so one timer is all it can honour.
203.     const unsubscribers = forms.flatMap((form) => {
204.       const store = getStore(form.key);
205.       if (!store) return [];
206.       return [
207.         store.sub(responsesAtom, () => {
208.           if (finishedRef.current) return;
209.           // An edit is a change to the DRAFT-SAFE partition. Structured
210.           // types with draftPolicy "exclude" write prefetched server rows
211.           // into the store from mount effects; treating those writes as
212.           // edits marked untouched clinical forms dirty and persisted a
213.           // phantom draft over the clinician's real one.
214.           //
215.           // Only THIS form's part is re-serialized — the fired store is
216.           // the only one that could have changed — and compared against
217.           // this form's own cached entry.
218.           const signature = formSignature(form, store);
219.           if (formSignatures.get(form.key) === signature) return;
220.           formSignatures.set(form.key, signature);
221.           setDirty(true);
222.           clearTimeout(timer);
223.           timer = setTimeout(() => {
224.             timer = undefined;
225.             persistNow();
226.           }, AUTOSAVE_DEBOUNCE_MS);
227.         }),
228.       ];
229.     });
230. 
231.     // pagehide covers reload/close/bfcache; unmount covers in-app nav.
232.     window.addEventListener("pagehide", flush);
233.     return () => {
234.       window.removeEventListener("pagehide", flush);
235.       flush();
236.       for (const unsubscribe of unsubscribers) unsubscribe();
237.     };
238.     // storesVersion re-runs the subscription when a form (un)registers.
239.   }, [storesVersion, forms, getStore, persistNow]);
240. 
241.   /** Successful submit: drop the stored draft, stop all further saves,
242.    *  and clear the dirty flag SYNCHRONOUSLY (flushSync) — the success
243.    *  handler navigates right after this, and `useNavigationPrompt` must
244.    *  already see a pristine page or it blocks the redirect (the same
245.    *  reason the legacy form flushSync'd `setIsDirty(false)`).
246.    *
247.    *  The clear runs off `scope`, not off whether this session PERSISTED
248.    *  locally: a server-draft session shares its key with the plain mount,
249.    *  and a local draft left behind there would prompt Resume with answers
250.    *  this submit already filed. */
251.   const finishDraft = useCallback(() => {
252.     finishedRef.current = true;
253.     const current = scopeRef.current;
254.     if (current) clearFillDraft(current);
255.     flushSync(() => {
256.       setDirty(false);
257.       setRestoreDismissed(true);
258.     });
259.   }, []);
260. 
261.   const discardRestoredDraft = useCallback(() => {
262.     const current = scopeRef.current;
263.     if (current) clearFillDraft(current);
264.     // Discard drops the STORED draft — never what is on screen. The draft
265.     // only ever reaches the stores through Resume, so while the bar shows
266.     // they hold nothing but this session's own work: prefetched clinical
267.     // rows and whatever the clinician typed while ignoring the prompt.
268.     // Resetting them would destroy exactly the un-persisted work the
269.     // prompt gate protects.
270.     //
271.     // Persistence was standing down while the prompt was pending — flip
272.     // the gate synchronously (the ref recomputes only on the next render)
273.     // and write now, so anything typed in the meantime becomes a fresh
274.     // draft of its own instead of living un-persisted until the next
275.     // keystroke. An untouched session hits saveFillDraft's clear-on-empty
276.     // branch, which is a no-op on the already-cleared key.
277.     restorePendingRef.current = false;
278.     setRestoreDismissed(true);
279.     persistNow();
280.   }, [persistNow]);
281. 
282.   const dismissRestoreBar = useCallback(() => setRestoreDismissed(true), []);
283. 
284.   /** Apply the restored draft — the prompt bar's Resume affordance. The
285.    *  primary form's snapshot lands in the live store through the shared
286.    *  overlay rule; every other snapshot goes back to the host, which
287.    *  re-adds those questionnaires seeded from their snapshots. */
288.   const resumeRestoredDraft = useCallback(() => {
289.     const draft = restoredDraftRef.current;
290.     if (!draft) return;
291.     const primary = forms.find((form) => form.isPrimary);
292.     const addedSnapshots: DraftFormSnapshot[] = [];
293.     for (const snapshot of draft.forms) {
294.       if (primary && snapshot.questionnaireId === primary.key) {
295.         const store = getStore(primary.key);
296.         if (store) {
297.           store.set(
298.             responsesAtom,
299.             preserveExcludedStructured(
300.               store.get(responsesAtom),
301.               mergeDraftIntoSeed(
302.                 primary.questionnaire.questions,
303.                 snapshot.responses,
304.               ),
305.             ),
306.           );
307.         }
308.         continue;
309.       }
310.       addedSnapshots.push(snapshot);
311.     }
312.     if (addedSnapshots.length > 0) onResumeAddedForms(addedSnapshots);
313.     setDirty(true);
314.     setRestoreDismissed(true);
315.   }, [forms, getStore, onResumeAddedForms]);
316. 
317.   return {
318.     /** Any edit since mount — drives the Draft chip. A merely-detected
319.      *  draft is NOT dirty; the chip lights only after Resume or an edit. */
320.     dirty,
321.     restoredDraft: restoreDismissed ? undefined : restoredDraft,
322.     discardRestoredDraft,
323.     dismissRestoreBar,
324.     resumeRestoredDraft,
325.     /** For the submit-success path: the draft served its purpose. */
326.     finishDraft,
327.   };
328. }
