1. import { useMutation, useQueryClient } from "@tanstack/react-query";
2. import { useCallback, useMemo, useSyncExternalStore } from "react";
3. import { useTranslation } from "react-i18next";
4. import { toast } from "sonner";
5. 
6. import careConfig from "@careConfig";
7. 
8. import { responsesAtom } from "@/components/QuestionnaireV2/form/engine/store";
9. import {
10.   getStructuredTypesVersion,
11.   subscribeToStructuredTypes,
12. } from "@/components/QuestionnaireV2/structured/pluginRegistry";
13. import { resolveStructuredType } from "@/components/QuestionnaireV2/structured/registry";
14. 
15. import { draftResponseForStorage } from "@/components/QuestionnaireV2/fill/draft/fillDraftStore";
16. import { unsupportedDraftStructuredTypes } from "@/components/QuestionnaireV2/fill/draft/unsupportedDraftStructuredTypes";
17. import type { FillFormEntry } from "@/components/QuestionnaireV2/fill/formSession";
18. import type { FormStore } from "@/components/QuestionnaireV2/fill/StoreRegistrar";
19. import type { FillSubject } from "@/components/QuestionnaireV2/fill/subject";
20. 
21. import type { FormSubmissionRead } from "@/types/questionnaire/formSubmission";
22. import formSubmissionApi from "@/types/questionnaire/formSubmissionApi";
23. import mutate from "@/Utils/request/mutate";
24. 
25. interface UseSaveServerDraftArgs {
26.   /** Every questionnaire in the session, primary first. */
27.   forms: FillFormEntry[];
28.   getStore: (key: string) => FormStore | undefined;
29.   subject: FillSubject;
30.   /** Set when this session resumed a server draft — saving PUTs the same
31.    *  record instead of creating a second one. */
32.   continueDraftId?: string;
33.   /** The server copy is now authoritative: the host drops the local
34.    *  autosave draft, flushes pristine and leaves the page. */
35.   onSaved: () => void;
36. }
37. 
38. /**
39.  * The deliberate "Save as draft" — a SERVER draft (`form_submission` with
40.  * status `draft`), which is what makes a half-finished form reachable from
41.  * another device and from the encounter overview's drafts card. It is a
42.  * different thing from `useFillSessionAutosave`, the crash-safety net that
43.  * writes localStorage only: this one is explicit, survives the browser, and
44.  * ends the session.
45.  *
46.  * The availability rules follow from the dump's shape and from the way
47.  * drafts are FOUND again:
48.  * - feature-flagged (`enableQuestionnaireDraft`);
49.  * - encounter subjects only. This one is a DELIBERATE NARROWING of legacy,
50.  *   not a port of it: legacy offered "Save as draft" on its patient mount
51.  *   too, and those saves produced orphaned records. The sole listing of
52.  *   server drafts is the encounter overview's card, which filters
53.  *   `form_submission` by `encounter`; a patient-mount draft POSTs without
54.  *   one, so nothing can ever surface it — and saving also drops the local
55.  *   autosave copy, making that draft unreachable rather than merely
56.  *   inconvenient. Widening this back needs a listing surface first;
57.  * - a single form per session — `response_dump.questionnaireResponses` is
58.  *   ONE `{questionnaire, responses}` pair, so a multi-form session cannot
59.  *   be represented without silently dropping forms;
60.  * - no structured question this deployment cannot dump faithfully
61.  *   (`unsupportedDraftStructuredTypes`): a contract-v1 type conflates
62.  *   prefetched server rows with user input, so restoring its dump later
63.  *   could re-upsert clinical data edited elsewhere (the same reason
64.  *   `draftPolicy: "exclude"` exists for the local draft) — contract v2
65.  *   dumps the edit log alone and re-projects onto a fresh baseline, so it
66.  *   lifts that restriction, except for `files` (`draftPolicy: "exclude"`
67.  *   under both contracts) and a type this deployment cannot resolve.
68.  *
69.  * Resuming a server draft and saving it again IS allowed: that PUTs the
70.  * same id, which is how a draft gets iterated across sessions.
71.  */
72. export function useSaveServerDraft({
73.   forms,
74.   getStore,
75.   subject,
76.   continueDraftId,
77.   onSaved,
78. }: UseSaveServerDraftArgs) {
79.   const { t } = useTranslation();
80.   const queryClient = useQueryClient();
81. 
82.   const encounterBound = subject.type === "encounter" ? subject : undefined;
83.   const primary = forms.find((form) => form.isPrimary);
84. 
85.   // `unsupportedDraftStructuredTypes` calls `resolveStructuredType`, whose
86.   // answer for a plugin-authored question changes when that plugin's
87.   // remote registers or unregisters its type — subscribing (same pattern
88.   // as `QuestionTypePicker.tsx` over this same registry) recomputes
89.   // `canSaveDraft` when that happens, instead of caching a stale answer
90.   // for the lifetime of this hook.
91.   const structuredTypesVersion = useSyncExternalStore(
92.     subscribeToStructuredTypes,
93.     getStructuredTypesVersion,
94.     getStructuredTypesVersion,
95.   );
96. 
97.   const canSaveDraft = useMemo(() => {
98.     if (!careConfig.enableQuestionnaireDraft) return false;
99.     if (!encounterBound || !primary) return false;
100.     if (forms.length !== 1) return false;
101.     return (
102.       unsupportedDraftStructuredTypes(
103.         primary.questionnaire.questions,
104.         resolveStructuredType,
105.       ).length === 0
106.     );
107.   }, [encounterBound, primary, forms.length, structuredTypesVersion]);
108. 
109.   const handleSaved = useCallback(
110.     (saved: FormSubmissionRead) => {
111.       if (continueDraftId) {
112.         // Write the PUT's response straight into the cache instead of
113.         // invalidating and hoping a refetch lands: `saved` is a
114.         // `FormSubmissionRead`, the exact shape `formSubmissionApi.get`
115.         // caches at this same key, so this is provably a fresh, correctly
116.         // shaped replacement — not a guess.
117.         //
118.         // The cancel-with-revert trap this avoids: `query()` forwards the
119.         // query's AbortSignal to `fetch` (Utils/request/query.ts), and
120.         // `onSaved` below navigates away in this same tick. If we instead
121.         // called `invalidateQueries`, the resulting refetch would still be
122.         // in flight when this component's observer unmounts on navigate —
123.         // React Query v5 cancels that fetch and REVERTS the cache to
124.         // whatever was there before (the pre-PUT dump), not the fresh
125.         // record, and not even a "stale" marker that would force a real
126.         // refetch next time. A later re-resume of this draft gates on
127.         // `isLoading` (present in cache => not loading) and seeds the form
128.         // ONCE from that stale cache, so the just-saved edits would
129.         // silently vanish on re-entry. Replacing the cache entry directly
130.         // sidesteps the refetch entirely.
131.         queryClient.setQueryData(["formSubmission", continueDraftId], saved);
132.       }
133.       // The encounter overview's drafts card lists these. This is a
134.       // DIFFERENT query key (`["formSubmissions", encounterId]`, a list) —
135.       // it isn't affected by the trap above because that card doesn't
136.       // navigate away when it invalidates itself (discarding a draft keeps
137.       // the overview mounted), so its own refetch is never cancelled.
138.       queryClient.invalidateQueries({ queryKey: ["formSubmissions"] });
139.       toast.success(t("draft_saved_successfully"));
140.       onSaved();
141.     },
142.     [continueDraftId, queryClient, t, onSaved],
143.   );
144. 
145.   const handleFailed = useCallback(() => {
146.     toast.error(t("draft_save_failed"));
147.   }, [t]);
148. 
149.   const { mutate: createDraft, isPending: isCreating } = useMutation({
150.     mutationFn: mutate(formSubmissionApi.create),
151.     onSuccess: handleSaved,
152.     onError: handleFailed,
153.   });
154. 
155.   const { mutate: updateDraft, isPending: isUpdating } = useMutation({
156.     mutationFn: mutate(formSubmissionApi.update, {
157.       pathParams: { external_id: continueDraftId ?? "" },
158.     }),
159.     onSuccess: handleSaved,
160.     onError: handleFailed,
161.   });
162. 
163.   const saveDraft = useCallback(() => {
164.     if (!canSaveDraft || !primary || !encounterBound) return;
165.     const store = getStore(primary.key);
166.     if (!store) return;
167. 
168.     // Exactly the shape this page's own `?continue_draft=` restore parses,
169.     // and the one `composeBatch` finalizes on submit.
170.     const response_dump = {
171.       questionnaireResponses: {
172.         questionnaire: primary.questionnaire,
173.         responses: Object.values(store.get(responsesAtom)).map(
