171.         // `validate` for the same reason. What the UI shows as inert must
172.         // not submit behind its back.
173.         if (renderFailed?.has(question.id)) continue;
174.         // The recorded entries must belong to this question's type — the
175.         // guard `structuredDataOf` used to carry, kept now that the data
176.         // read is untyped.
177.         if (response.structured_type !== question.structured_type) continue;
178.         // The same slot-state predicate the renderer (`StructuredSlot`) and
179.         // both submit-time validators (`form/validation.ts`,
180.         // `fill/submit/validateStructured.ts`) read — `unknown_type`
181.         // (plugin disabled), `subject_mismatch` (a type authored onto a
182.         // questionnaire whose subject_type it doesn't declare — legacy
183.         // data; the studio picker now prevents this going forward), and
184.         // `missing_context` all skip here. The last is the fix: draft-
185.         // restored data under a slot whose required context id the mount
