207.         // section displaying twelve prefetched rows and holding no edits
208.         // contributes zero requests, before any type code runs.
209.         if (structuredEditsOf(response).length === 0) continue;
210.         structuredWork.push(
211.           buildStructuredRequests(definition, response, {
212.             patientId: patientBound?.patientId,
213.             encounterId: renderCtx.encounterId,
214.             facilityId: renderCtx.facilityId,
215.             questionId: question.id,
216.           }),
217.         );
218.         continue;
219.       }
220. 
221.       // Every plain leaf goes through serialization; the content decision
222.       // is `serializeResponseValues`' alone (its filter keeps value-,
223.       // coding- and unit-carrying entries). Gating here on values[0]
