20. /**
21.  * Submit-time structured validation, and the ONE place that decides
22.  * whether a broken structured slot blocks the submit.
23.  *
24.  * Every enabled structured question resolves the same slot state
25.  * `StructuredSlot` renders from (plus the render-failed set its error
26.  * boundary writes) — the shared resolver documented on
27.  * `StructuredSlotState`. Whatever that comes back with other than `ready`
28.  * means the clinician has no input to answer: an unknown/disabled type, a
29.  * subject the type doesn't declare, a context id this mount can't supply,
30.  * or a component that threw. `composeBatch` drops that question's data
31.  * regardless of what's recorded, so the fork here is stark:
32.  *   - REQUIRED — the section is unusable but was supposed to be answered.
33.  *     Fail-open here would submit the rest of the form and quietly leave
34.  *     that section out, with a success toast telling the clinician nothing
35.  *     was wrong. So this hard-blocks, one error, naming the question by
36.  *     its own text (`structured_section_unavailable_required`) — the
37.  *     clinician learns exactly which section and that saving is impossible
38.  *     until it loads.
39.  *   - not required — the section was always optional; skipping it here
40.  *     matches `composeBatch` exactly, and `StructuredSlot`'s notice tells
41.  *     the clinician its entries won't be submitted.
42.  * `collectRequiredErrors` stays out of this decision entirely (it just
43.  * avoids double-erroring the same question — see its comment), so this is
44.  * the one and only source of a broken-slot error.
45.  *
46.  * A `ready` question still runs its type's `validate` (core and plugin
47.  * definitions alike). `t` is threaded the same way `collectRequiredErrors`
48.  * takes it — errors carry finished message text, not keys.
49.  */
50. export function collectStructuredErrors(
51.   questionnaire: QuestionnaireRead,
52.   responses: Record<string, QuestionnaireResponse>,
53.   subject: RendererSubject,
54.   renderFailed: ReadonlySet<string>,
55.   t: TFunction,
56. ): QuestionValidationError[] {
57.   const linkIndex = buildLinkIndex(questionnaire.questions);
58.   const errors: QuestionValidationError[] = [];
59. 
60.   const walk = (list: Question[]) => {
61.     for (const question of list) {
62.       if (!isQuestionEnabledInState(question, responses, linkIndex)) continue;
63.       if (question.type === "group") {
64.         walk(question.questions ?? []);
65.         continue;
66.       }
67.       if (question.type !== "structured" || !question.structured_type) {
68.         continue;
69.       }
70.       const type = question.structured_type;
71.       // The component threw (error boundary's own store) OR the resolver
72.       // says anything but `ready` — unknown/disabled type, subject
73.       // mismatch, missing context. Either way the slot shows a notice, not
74.       // an input: a required question in this state hard-blocks, named; a
75.       // non-required one is simply skipped, same as `composeBatch`. Skip
76.       // resolving state at all once render already failed — there is
77.       // nothing left to read a `ready` definition from.
78.       const state = renderFailed.has(question.id)
79.         ? undefined
80.         : resolveStructuredSlotState(type, questionnaire.subject_type, subject);
81.       if (!state || state.kind !== "ready") {
82.         if (question.required) {
83.           errors.push({
84.             question_id: question.id,
85.             error: t("structured_section_unavailable_required", {
86.               label: question.text,
87.             }),
88.           });
89.         }
90.         continue;
91.       }
92.       const definition = state.definition;
93.       if (!definition.validate) continue;
94.       const response = responses[question.id];
95.       // The recorded entries must belong to this question's type — the
96.       // guard `structuredDataOf` used to carry, kept now that the data
97.       // read is untyped.
98.       if (response?.structured_type !== type) continue;
99.       const required = question.required ?? false;
100.       const projection = structuredDataAny(response);
101.       const edits = structuredEditsOf(response);
102.       // Nothing recorded AND nothing changed. The two halves answer
103.       // different questions, so neither may gate the other: a
104.       // NON-empty projection with an empty log still runs (a required
105.       // section satisfied by rows the server already had); a non-empty log
106.       // with an empty projection still runs (the clinician removed every
107.       // row).
108.       if (projection.length === 0 && edits.length === 0) continue;
109.       try {
110.         errors.push(
111.           ...definition.validate(projection, edits, question.id, required),
112.         );
113.       } catch (error) {
114.         // Plugin code runs here. An escaping throw used to propagate out of
115.         // `submit()` (invoked as `void submit()`), so Save Changes became a
116.         // silent no-op for the WHOLE session — no toast, no panel, no
117.         // batch. Contain it the way `invokeAction` contains a thrown plugin
118.         // action: one question-scoped error the clinician can see and act
119.         // on, and the submit aborts through the normal validation path.
120.         console.error(
121.           `Structured type "${type}" threw while validating question ${question.id}`,
122.           error,
123.         );
124.         errors.push({
125.           question_id: question.id,
126.           error: t("structured_question_validate_failed"),
127.         });
128.       }
129.     }
130.   };
131.   walk(questionnaire.questions);
132.   return errors;
133. }
