58. /**
59.  * Validate and extract a resumed server draft's responses. The embedded
60.  * questionnaire id must match the live one. `response_dump` is a free-form JSON blob the server never
61.  * validates, so its shape is checked at runtime instead of trusted with a
62.  * cast: a malformed dump lands on the "draft not recoverable" branch here
63.  * rather than surfacing as crashes deep in the renderer.
64.  */
65. function parseServerDraft(
66.   serverDraft: FormSubmissionRead,
67.   questionnaire: QuestionnaireRead,
68. ): ServerDraftState {
69.   // Only an open draft resumes. A record already submitted (or marked
70.   // entered-in-error) re-opening as editable would let one submission
71.   // file twice — the overview's drafts card filters these out, but the
72.   // URL is shareable and outlives that filter.
73.   if (serverDraft.status !== "draft") {
74.     return { mismatch: true };
75.   }
76.   const dump: unknown = serverDraft.response_dump;
77.   const form = isRecord(dump) ? dump.questionnaireResponses : undefined;
78.   if (
79.     !isRecord(form) ||
80.     !isRecord(form.questionnaire) ||
81.     form.questionnaire.id !== questionnaire.id ||
82.     !Array.isArray(form.responses)
83.   ) {
84.     return { mismatch: true };
85.   }
86.   const record: Record<string, QuestionnaireResponse> = {};
87.   for (const item of form.responses as unknown[]) {
88.     if (!isRecord(item) || typeof item.question_id !== "string") {
89.       return { mismatch: true };
90.     }
91.     // Beyond `question_id` the entry is trusted as a QuestionnaireResponse
92.     // this page's own save path wrote; `reviveDraftResponses` defends the
93.     // date fields it touches.
94.     record[item.question_id] = item as unknown as QuestionnaireResponse;
95.   }
96.   return { mismatch: false, responses: reviveDraftResponses(record) };
97. }
